USE todo_app;

DROP TABLE IF EXISTS studenten;

CREATE TABLE studenten (
    id              INT UNSIGNED NOT NULL AUTO_INCREMENT,
    voornaam        VARCHAR(50)  NOT NULL,
    tussenvoegsel   VARCHAR(20)  NULL,
    achternaam      VARCHAR(80)  NOT NULL,
    geboortedatum   DATE         NOT NULL,
    geslacht        ENUM('M','V','X') NOT NULL,
    email           VARCHAR(150) NOT NULL,
    telefoonnummer  VARCHAR(15)  NULL,
    straat          VARCHAR(100) NOT NULL,
    huisnummer      VARCHAR(10)  NOT NULL,
    postcode        CHAR(7)      NOT NULL,
    woonplaats      VARCHAR(60)  NOT NULL,
    afstand_tot_nyp DECIMAL(3,1) NOT NULL DEFAULT 0.0,
    updated_at     TIMESTAMP    NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
    PRIMARY KEY (id),
    UNIQUE KEY uq_studenten_email (email)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

